public void MoveZeroes(int[] nums)
{
    int[] temp = new int[nums.Length];
    int idx = 0;
    foreach (int n in nums)
        if (n != 0) temp[idx++] = n;
    Array.Copy(temp, nums, nums.Length);
}

public void MoveZeroes(int[] nums)
{
    int lastNonZero = 0;
    for (int i = 0; i < nums.Length; i++)
    {
        if (nums[i] != 0)
        {
            (nums[lastNonZero], nums[i]) = (nums[i], nums[lastNonZero]);
            lastNonZero++;
        }
    }
}
